SELECT name, category, price
FROM (SELECT *, AVG(price) OVER (PARTITION BY category) AS cat_avg FROM products)
WHERE price > cat_avg;

SELECT ROUND(AVG(total), 2) AS aov FROM (
  SELECT order_id, SUM(quantity * unit_price) AS total
  FROM order_items
  GROUP BY order_id
);

SELECT o.id AS order_id
FROM orders o
WHERE NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.id);
